// Package web serves the Vue workbench bundled into the Go executable.
package web

import (
	"embed"
	"mime"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
)

// staticFiles is generated by `npm --prefix frontend run build`.
// Keep the production bundle in Git so a Go-only checkout can still build.
//
//go:embed static
var staticFiles embed.FS

// Controller serves the same-origin workbench and its hashed assets.
type Controller struct{}

func NewController() *Controller { return &Controller{} }

func (ctl *Controller) Index(c *gin.Context) {
	content, err := staticFiles.ReadFile("static/index.html")
	if err != nil {
		c.Status(http.StatusInternalServerError)
		return
	}
	c.Header("Cache-Control", "no-cache")
	c.Data(http.StatusOK, "text/html; charset=utf-8", content)
}

// Asset serves only Vite's flat assets directory; unknown paths never fall back
// to HTML. Hash routing keeps workbench navigation independent of API routes.
func (ctl *Controller) Asset(c *gin.Context) {
	name := strings.TrimPrefix(c.Param("filepath"), "/")
	if name == "" || strings.ContainsAny(name, "/\\") || strings.HasPrefix(name, ".") {
		c.Status(http.StatusNotFound)
		return
	}
	content, err := staticFiles.ReadFile("static/assets/" + name)
	if err != nil {
		c.Status(http.StatusNotFound)
		return
	}
	contentType := "application/octet-stream"
	if dot := strings.LastIndexByte(name, '.'); dot >= 0 {
		if value := mime.TypeByExtension(name[dot:]); value != "" {
			contentType = value
		}
	}
	c.Header("Cache-Control", "public, max-age=31536000, immutable")
	c.Header("X-Content-Type-Options", "nosniff")
	c.Data(http.StatusOK, contentType, content)
}
